using System;using System.IO;using Emberfall;
public static class ReturningCounterPersistenceTests{
 static int n;static void Check(bool ok,string s){n++;if(!ok)throw new Exception(s);}
 public static string Run(string root){var p=new ProgressionService(Path.Combine(root,"counter"));Check(p.CreateNewSlot(HeroClass.Vanguard),"create sword save");p.Profile.level=20;p.Profile.mechanicMaterials=40;p.Profile.gold=100000;p.Profile.bestFloor=5;p.Save();var item=p.CreateMechanicItem(EquipmentMechanic.ReturningBlade);Check(p.CollectLoot(item)&&p.Equip(item.id),"collect actual mechanism");string id=item.id;Check(p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==0,"legacy defaultA");Check(!p.ToggleMechanicVariant(id,false),"camp required");Check(p.ToggleMechanicVariant(id,true)&&p.Profile.mechanicMaterials==36,"firstB unlock four shards");Check(p.Profile.inventory.Find(x=>x.id==id).mechanicVariantUnlocked&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"selectedB survives transaction validation");Check(p.SaveBuildPreset(0,true),"captureB build");Check(p.ToggleMechanicVariant(id,true)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==0&&p.Profile.mechanicMaterials==36,"A toggle free");Check(p.ApplyBuildPreset(0,true)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"actual build apply restoresB");Check(p.LoadSlot(p.CurrentSlotId)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"reload retainsB");Check(p.AscendMechanic(id,true)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1&&p.Profile.inventory.Find(x=>x.id==id).rarity==Rarity.Legendary,"ascension retainsB");p.Profile.level=30;p.Save();var unchanged=UnityEngine.JsonUtility.ToJson(p.Profile,true);string unchangedDisk=File.ReadAllText(p.SaveFilePath);Check(p.QuoteReforge(id,25)==null&&!p.ReforgeMechanic(p.QuoteReforge(id,25),true)&&unchanged==UnityEngine.JsonUtility.ToJson(p.Profile,true)&&unchangedDisk==File.ReadAllText(p.SaveFilePath),"rounded25 quote is non-increasing and cannot change storage or variant");var quote=p.QuoteReforge(id,30);var preview=p.PreviewReforge(quote);int goldBefore=p.Profile.gold;Check(quote!=null&&quote.TargetLevel==30&&p.ReforgeMechanic(quote,true)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"reforge retainsB");var reforged=p.Profile.inventory.Find(x=>x.id==id);Check(reforged.id==id&&reforged.rarity==Rarity.Legendary&&reforged.attack==preview.attack&&reforged.defense==preview.defense&&reforged.health==preview.health&&reforged.upgradeLevel==preview.upgradeLevel&&p.Profile.gold==goldBefore-quote.GoldCost,"reforge preserves identity rarity variant and preview attributes with one exact charge");Check(p.LoadSlot(p.CurrentSlotId)&&p.Profile.inventory.Find(x=>x.id==id).level==30&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1&&p.Profile.inventory.Find(x=>x.id==id).attack==preview.attack&&p.Profile.inventory.Find(x=>x.id==id).defense==preview.defense&&p.Profile.inventory.Find(x=>x.id==id).health==preview.health,"reforged reload retainsB and every preview attribute");p.Profile.inventory.Find(x=>x.id==id).mechanicVariantUnlocked=false;p.Profile.inventory.Find(x=>x.id==id).mechanicVariant=1;p.Save();Check(p.LoadSlot(p.CurrentSlotId)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==0,"locked forgedB sanitizesA");return "PASS "+n+" actual variant unlock/build/save/ascension/reforge assertions";}}
